def load():
    """返回 {技能ID: {name, group, step, rng, cast, row, col, nosel, equip}}"""
    out = {}
    for seg in ROWS.split("|"):
        p = seg.split(":")
        if len(p) != 10:
            continue
        sid, ni, g, st, rng, cast, r, c, nt, eq = (int(x) for x in p)
        out[sid] = {"name": NAMES[ni], "group": g, "step": st,
                    "rng": rng, "cast": cast, "row": r, "col": c,
                    "nosel": (nt == 0), "equip": (eq == 1)}
    return out
